<?php
namespace Sellio\Connector;
defined( 'ABSPATH' ) || exit;
final class Rest_API {
	public static function init() { add_action( 'rest_api_init', array( __CLASS__, 'routes' ) ); }
	public static function routes() { $p = array( 'methods' => 'GET', 'permission_callback' => array( __CLASS__, 'permission' ) ); register_rest_route( 'sellio/v1', '/connection', $p + array( 'callback' => array( __CLASS__, 'connection' ) ) ); register_rest_route( 'sellio/v1', '/products', $p + array( 'callback' => array( __CLASS__, 'products' ), 'args' => array( 'page' => array( 'default' => 1 ), 'per_page' => array( 'default' => 50 ), 'modified_after' => array() ) ) ); register_rest_route( 'sellio/v1', '/products/(?P<id>\\d+)', $p + array( 'callback' => array( __CLASS__, 'product' ) ) ); register_rest_route( 'sellio/v1', '/products/(?P<id>\\d+)/variations', $p + array( 'callback' => array( __CLASS__, 'variations' ) ) ); register_rest_route( 'sellio/v1', '/orders/(?P<id>\\d+)/status', array( 'methods' => 'POST', 'permission_callback' => array( __CLASS__, 'permission' ), 'callback' => array( __CLASS__, 'update_order_status' ), 'args' => array( 'status' => array( 'required' => true ) ) ) ); }
	public static function permission( $request ) { $token = $request->get_header( 'x-sellio-catalog-token' ); $hash = get_option( 'sellio_connector_catalog_token_hash' ); return $token && $hash && hash_equals( $hash, hash( 'sha256', $token ) ); }
	public static function connection() { $s = Settings::all(); return rest_ensure_response( array( 'store_id' => $s['store_id'], 'site_name' => get_bloginfo( 'name' ), 'site_url' => home_url(), 'currency' => get_woocommerce_currency(), 'timezone' => wp_timezone_string(), 'contract_version' => '1', 'plugin_version' => SELLIO_CONNECTOR_VERSION, 'capabilities' => array( 'products', 'variations', 'modified_after' ) ) ); }
	public static function products( $r ) { $per = min( 100, max( 1, absint( $r['per_page'] ) ) ); $args = array( 'limit' => $per, 'page' => max( 1, absint( $r['page'] ) ), 'paginate' => true, 'orderby' => 'ID', 'order' => 'ASC', 'type' => array( 'simple', 'variable', 'grouped', 'external' ) ); if ( $r['modified_after'] ) { $args['date_modified'] = '>' . sanitize_text_field( $r['modified_after'] ); } $result = wc_get_products( $args ); $response = rest_ensure_response( array_map( array( 'Sellio\\Connector\\Serializer', 'product' ), $result->products ) ); $response->header( 'X-WP-Total', $result->total ); $response->header( 'X-WP-TotalPages', $result->max_num_pages ); return $response; }
	public static function product( $r ) { $p = wc_get_product( absint( $r['id'] ) ); return $p ? rest_ensure_response( Serializer::product( $p ) ) : new \WP_Error( 'sellio_not_found', __( 'Produkt nie istnieje.', 'sellio-connector' ), array( 'status' => 404 ) ); }
	public static function variations( $r ) { $p = wc_get_product( absint( $r['id'] ) ); if ( ! $p || ! $p->is_type( 'variable' ) ) { return new \WP_Error( 'sellio_not_found', __( 'Produkt wariantowy nie istnieje.', 'sellio-connector' ), array( 'status' => 404 ) ); } return rest_ensure_response( array_map( static function( $id ) { $v = wc_get_product( $id ); $d = Serializer::product( $v ); $d['inherits_manage_stock'] = 'parent' === $v->get_manage_stock(); return $d; }, $p->get_children() ) ); }
	public static function update_order_status( $r ) { $order = wc_get_order( absint( $r['id'] ) ); if ( ! $order ) { return new \WP_Error( 'sellio_not_found', __( 'Zamówienie nie istnieje.', 'sellio-connector' ), array( 'status' => 404 ) ); } $status = sanitize_key( $r['status'] ); if ( ! in_array( $status, array( 'pending', 'on-hold', 'processing', 'completed', 'cancelled', 'refunded', 'failed' ), true ) ) { return new \WP_Error( 'sellio_status', __( 'Nieprawidłowy status zamówienia.', 'sellio-connector' ), array( 'status' => 400 ) ); } $order->update_status( $status, __( 'Status zmieniony z Sellio.', 'sellio-connector' ) ); return rest_ensure_response( array( 'id' => (string) $order->get_id(), 'status' => $order->get_status() ) ); }
}
